from collections import deque, defaultdict

class Solution:
    def analyzeHierarchy(self, employees):
        info = {e[0]: e for e in employees}
        children = defaultdict(list)
        root = None
        parent = {}
        for eid, name, mgr, sal, dept in employees:
            if mgr is None:
                root = eid
            else:
                children[mgr].append(eid)
                parent[eid] = mgr
        res = []
        for eid in info:
            lvl, cur = 1, eid
            while cur in parent:
                cur = parent[cur]
                lvl += 1
            q = deque([eid])
            size, bud = 0, info[eid][3]
            while q:
                u = q.popleft()
                for v in children[u]:
                    size += 1
                    bud += info[v][3]
                    q.append(v)
            res.append([eid, info[eid][1], lvl, size, bud])
        res.sort(key=lambda r: (r[2], -r[4], r[1]))
        return res

