import java.util.*;

class Solution {
    public int[][] analyzeHierarchy(int[][] employees) {
        Map<Integer, List<Integer>> ch = new HashMap<>();
        Map<Integer, Integer> par = new HashMap<>(), sal = new HashMap<>();
        int root = -1;
        for (int[] e : employees) {
            int id = e[0], mgr = e[2], s = e[3];
            sal.put(id, s);
            if (mgr == -1) root = id;
            else { ch.computeIfAbsent(mgr, k -> new ArrayList<>()).add(id); par.put(id, mgr); }
        }
        List<int[]> rows = new ArrayList<>();
        for (int[] e : employees) {
            int id = e[0], lvl = 1;
            while (par.containsKey(id)) { id = par.get(id); lvl++; }
            Deque<Integer> st = new ArrayDeque<>(); st.push(e[0]);
            int size = 0, bud = e[3];
            while (!st.isEmpty()) {
                int u = st.pop();
                for (int v : ch.getOrDefault(u, Collections.emptyList())) { size++; bud += sal.get(v); st.push(v); }
            }
            rows.add(new int[]{e[0], lvl, size, bud});
        }
        rows.sort((a, b) -> a[1] != b[1] ? a[1] - b[1]
                : a[3] != b[3] ? b[3] - a[3] : 0);
        int[][] out = new int[rows.size()][];
        return rows.toArray(out);
    }
}

