            order.append((u, done))
            if not done:
                stack.append((u, True))
                for v in children[u]:
                    stack.append((v, False))
        size, budget, level = {}, {}, {root: 1}
        for u, done in reversed(order):
            if done:
                s, b = 0, info[u][3]
