#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    struct Row { int id; string name; int level; long long size, budget; };
    vector<vector<long long>> analyzeHierarchy(vector<vector<string>>& employees) {
        unordered_map<int, pair<string,int>> info;
        unordered_map<int, vector<int>> ch;
        unordered_map<int, int> par;
        int root = -1;
        for (auto& e : employees) {
            int id = stoi(e[0]), mgr = e[2].empty() ? -1 : stoi(e[2]);
            info[id] = {e[1], stoi(e[3])};
            if (mgr == -1) root = id;
            else { ch[mgr].push_back(id); par[id] = mgr; }
        }
        vector<pair<int,bool>> order;
        vector<pair<int,bool>> st{{root,false}};
        while (!st.empty()) {
            auto [u, done] = st.back(); st.pop_back();
            order.push_back({u, done});
            if (!done) {
                st.push_back({u, true});
                for (int v : ch[u]) st.push_back({v, false});
            }
        }
        unordered_map<int,long long> sz, bud;
        unordered_map<int,int> lvl{{root,1}};
        for (auto it = order.rbegin(); it != order.rend(); ++it) {
            auto [u, done] = *it;
            if (done) {
                long long s = 0, b = info[u].second;
                for (int v : ch[u]) { s += 1 + sz[v]; b += bud[v]; }
                sz[u] = s; bud[u] = b;
            } else for (int v : ch[u]) lvl[v] = lvl[u] + 1;
        }
        vector<Row> rows;
        for (auto& [id, p] : info) rows.push_back({id, p.first, lvl[id], sz[id], bud[id]});
        sort(rows.begin(), rows.end(), [](const Row& a, const Row& b) {
            if (a.level != b.level) return a.level < b.level;
            if (a.budget != b.budget) return a.budget > b.budget;
            return a.name < b.name;
        });
        vector<vector<long long>> out;
        for (auto& r : rows) out.push_back({(long long)r.id, (long long)r.level, r.size, r.budget});
        return out;
    }
};

