import java.util.*;

class Solution {
    public int[][] analyzeHierarchy(int[][] employees) {
        Map<Integer, List<Integer>> ch = new HashMap<>();
        Map<Integer, Integer> sal = new HashMap<>();
        int root = -1;
        for (int[] e : employees) {
            sal.put(e[0], e[3]);
            if (e[2] == -1) root = e[0];
            else ch.computeIfAbsent(e[2], k -> new ArrayList<>()).add(e[0]);
        }
        List<int[]> order = new ArrayList<>();
        Deque<int[]> st = new ArrayDeque<>();
        st.push(new int[]{root, 0});
        while (!st.isEmpty()) {
            int[] cur = st.pop();
            order.add(cur);
            if (cur[1] == 0) {
                st.push(new int[]{cur[0], 1});
                for (int v : ch.getOrDefault(cur[0], Collections.emptyList())) st.push(new int[]{v, 0});
            }
        }
        Map<Integer, Long> sz = new HashMap<>(), bud = new HashMap<>();
        Map<Integer, Integer> lvl = new HashMap<>();
        lvl.put(root, 1);
        for (int i = order.size() - 1; i >= 0; i--) {
            int u = order.get(i)[0];
            if (order.get(i)[1] == 1) {
                long s = 0, b = sal.get(u);
                for (int v : ch.getOrDefault(u, Collections.emptyList())) { s += 1 + sz.get(v); b += bud.get(v); }
                sz.put(u, s); bud.put(u, b);
            } else for (int v : ch.getOrDefault(u, Collections.emptyList())) lvl.put(v, lvl.get(u) + 1);
        }
        List<int[]> rows = new ArrayList<>();
        for (int[] e : employees)
            rows.add(new int[]{e[0], lvl.get(e[0]), sz.get(e[0]).intValue(), bud.get(e[0]).intValue()});
        rows.sort((a, b) -> a[1] != b[1] ? a[1] - b[1] : b[3] - a[3]);
        return rows.toArray(new int[0][]);
    }
}

